arguments.command:
bash -lc 'set -euo pipefail; playlist="/tmp/fixtures_playlist.txt"; ipc="/tmp/mpv-socket"; rm -f "$ipc"; mpv --shuffle --loop=no --playlist="$playlist" --input-ipc-server="$ipc" >/dev/null 2>&1 & mpv_pid=$!; echo "MPV PID: $mpv_pid"; sleep 2; path=$(printf '{ "command": ["get_property","path"] }
' | socat - UNIX:"$ipc" 2>/dev/null | sed -n "s/.*"data":"\([^\"]*\)".*/\1/p"); echo "Initial track: $path"; printf '{ "command": ["playlist-next"] }
' | socat - UNIX:"$ipc" 2>/dev/null; sleep 2; path2=$(printf '{ "command": ["get_property","path"] }
' | socat - UNIX:"$ipc" 2>/dev/null | sed -n "s/.*"data":"\([^\"]*\)".*/\1/p"); echo "Track after next: $path2"; kill "$mpv_pid" 2>/dev/null || true'

